package ro.leo.visual;
import android.app.*;import android.content.*;import android.database.Cursor;import android.graphics.Color;import android.os.*;import android.provider.*;import android.view.*;import org.json.*;import java.io.*;import java.util.*;
/** Local contracts and real provider round trips. No operator requests, transfer or microphone capture. */
public final class Complete09Tests extends Instrumentation {
 int checks;Activity page;String prefix="complete09-"+UUID.randomUUID()+"-";ArrayList<String> prefs=new ArrayList<String>();Context fixture;android.net.Uri calendarRow,blockedRow;
 void check(boolean ok,String why){if(!ok)throw new AssertionError(why);checks++;}
 void clean(File f){File[] all=f.listFiles();if(all!=null)for(File child:all)if(!java.nio.file.Files.isSymbolicLink(child.toPath()))clean(child);else child.delete();f.delete();}
 Activity open(Intent intent){page=startActivitySync(intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final Activity a=page;runOnMainSync(new Runnable(){public void run(){a.getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON|WindowManager.LayoutParams.FLAG_TURN_SCREEN_ON);}});return a;}
 void close(){if(page!=null){final Activity a=page;runOnMainSync(new Runnable(){public void run(){a.finish();}});page=null;waitForIdleSync();}}
 public void onCreate(Bundle b){start();}
 public void onStart(){Bundle out=new Bundle();final Context c=getTargetContext();final File folder=new File(c.getCacheDir(),prefix);folder.mkdir();fixture=new ContextWrapper(c){public SharedPreferences getSharedPreferences(String name,int mode){if(!prefs.contains(name))prefs.add(name);return c.getSharedPreferences(prefix+name,mode);}public File getFilesDir(){return folder;}};
 try{
  ArrayList<GlobalSearchActivity.Hit> hits=new ArrayList<GlobalSearchActivity.Hit>();HashSet<String> seen=new HashSet<String>();check(ExtendedSearch.addSms(fixture,"hello","123","hello world",42,seen,hits),"SMS search matches body");check(hits.get(0).intent.getLongExtra("search_date",0)==42&&"123".equals(hits.get(0).intent.getStringExtra("thread")),"SMS result targets exact conversation/date");check(!ExtendedSearch.addSms(fixture,"hello","123","hello world",43,seen,hits),"provider/local duplicate removed");ConversationPrefs.toggle(fixture,"blocked","123");check(!ExtendedSearch.addSms(fixture,"hello","123","hello private",44,seen,hits),"filtered sender excluded from global results");
  File files=new File(folder,"files");files.mkdir();BackupEngine.write(new File(files,"Știre-test.txt"),new byte[]{1});File hidden=new File(files,".hidden-test.txt");BackupEngine.write(hidden,new byte[]{1});File android=new File(files,"Android");android.mkdir();BackupEngine.write(new File(android,"test-private.txt"),new byte[]{1});java.nio.file.Files.createSymbolicLink(new File(files,"test-escape.txt").toPath(),new File("/system/build.prop").toPath());ArrayList<File> found=ExtendedSearch.findFiles(Arrays.asList(files),"test");check(found.size()==1&&found.get(0).getName().equals("Știre-test.txt"),"file search skips hidden/app data and escaping symlink");
  check(CallToolsActivity.forwardCode("+40 721 123 456",true).equals("**21*+40721123456#"),"forward request uses normalized number");check(CallToolsActivity.forwardCode("",false).equals("##21#"),"forward removal code");boolean rejected=false;try{CallToolsActivity.forwardCode("*21*123#",true);}catch(IllegalArgumentException e){rejected=true;}check(rejected,"MMI injection rejected in destination");
  fixture.getSharedPreferences("accessibility",0).edit().putBoolean("contrast",true).putInt("text",2).commit();Appearance.Palette palette=Appearance.palette(fixture);check(palette.background==Color.BLACK&&palette.selection==Color.WHITE&&palette.ink==Color.BLACK,"high contrast palette applies before app theme");check(AccessibilityPrefs.scale(fixture)==1.3f,"extra large common text");fixture.getSharedPreferences("accessibility",0).edit().putInt("text",99).commit();check(AccessibilityPrefs.scale(fixture)==1.3f,"font preference bounded");
  fixture.getSharedPreferences("recorder",0).edit().putInt("quality",99).commit();check(RecorderProfile.selected(fixture)==2&&RecorderProfile.RATES[2]==44100,"recorder profile bounded");check(RecorderProfile.RATES[0]==16000&&RecorderProfile.BITS[0]==64000,"working voice profile retained");check(RecorderProfile.validName("Voice note")&&!RecorderProfile.validName("../outside")&&!RecorderProfile.validName("bad/name"),"recording rename boundary");long now=System.currentTimeMillis();check(RecorderLibraryActivity.accepts(2,now-86400000,now,false)&&!RecorderLibraryActivity.accepts(2,now-9L*86400000,now,false),"last-week recordings filter");check(RecorderLibraryActivity.accepts(3,0,now,true)&&!RecorderLibraryActivity.accepts(3,now,now,false),"recording favorites filter");
  check(BluetoothTransfers.percent(5,10)==50&&BluetoothTransfers.percent(15,10)==100&&BluetoothTransfers.percent(1,0)==-1,"Bluetooth progress bounded and unknown total");rejected=false;try{BluetoothTransfers.run(c,"cancel","1;invalid");}catch(SecurityException e){rejected=true;}check(rejected,"Bluetooth command argument injection rejected");JSONObject bluetooth=BluetoothTransfers.run(c,"list",null);check(bluetooth.has("rows")&&bluetooth.getJSONArray("rows").length()<=50,"real protected OPP provider readable through bridge");
  long own=CalendarReminders.calendar(c);if(own>=0){String title=prefix+"event";ContentValues event=new ContentValues();event.put("calendar_id",own);event.put("title",title);event.put("dtstart",now+3600000);event.put("dtend",now+7200000);event.put("eventTimezone",TimeZone.getDefault().getID());event.put("hasAlarm",0);calendarRow=c.getContentResolver().insert(CalendarContract.Events.CONTENT_URI,event);check(calendarRow!=null,"isolated temporary calendar event created");ArrayList<GlobalSearchActivity.Hit> calendar=new ArrayList<GlobalSearchActivity.Hit>();ExtendedSearch.calendar(c,prefix,calendar);check(calendar.size()==1&&calendar.get(0).intent.getLongExtra("event_id",-1)==ContentUris.parseId(calendarRow),"calendar search returns direct event target");c.getContentResolver().delete(calendarRow,null,null);calendarRow=null;}
  check(BlockedNumberContract.canCurrentUserBlockNumbers(c),"system user supports blocked numbers");String number="+999000"+(SystemClock.uptimeMillis()%1000000);if(!BlockedNumberContract.isBlocked(c,number)){ContentValues row=new ContentValues();row.put("original_number",number);blockedRow=c.getContentResolver().insert(BlockedNumberContract.BlockedNumbers.CONTENT_URI,row);check(blockedRow!=null&&BlockedNumberContract.isBlocked(c,number),"default dialer can block fixture through Android provider");c.getContentResolver().delete(blockedRow,null,null);blockedRow=null;check(!BlockedNumberContract.isBlocked(c,number),"fixture unblocked without touching personal records");}
  check(BackupEngine.allowed("accessibility","contrast","boolean")&&BackupEngine.category("accessibility").equals("settings"),"accessibility in selective settings backup");check(BackupEngine.allowed("recorder","quality","int")&&BackupEngine.category("recorder").equals("settings"),"recorder settings in backup");
  check(!ContextHelp.text("RecorderActivity").isEmpty()&&!ContextHelp.text("BluetoothTransfersActivity").isEmpty(),"context help for recorder and Bluetooth");
  for(Class<?> type:new Class<?>[]{CallToolsActivity.class,AccessibilitySettingsActivity.class,RecorderLibraryActivity.class,ContextHelpActivity.class}){open(new Intent(c,type));for(int n=0;n<60&&((LeoActivity)page).root==null;n++)SystemClock.sleep(100);check(((LeoActivity)page).root!=null,"new keypad screen opens: "+type.getSimpleName());close();}
  out.putString("result","PASS "+checks+" completion checks; no calls, transfers or recording started");
 }catch(Throwable e){out.putString("error",android.util.Log.getStackTraceString(e));}finally{close();if(calendarRow!=null)c.getContentResolver().delete(calendarRow,null,null);if(blockedRow!=null)c.getContentResolver().delete(blockedRow,null,null);for(String name:prefs)c.deleteSharedPreferences(prefix+name);clean(folder);}finish(out.containsKey("error")?Activity.RESULT_CANCELED:Activity.RESULT_OK,out);}
}
